"""Generated files merge by taking main's side of conflicts (.githooks/merge-generated)."""

from __future__ import annotations

import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DRIVER = ROOT / ".githooks" / "merge-generated"

LOCK = """version = 4

[[package]]
name = "app"
version = "0.1.0"
dependencies = [
 "serde",
]

[[package]]
name = "serde"
version = "1.0.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
"""

T_TOML = """# hand-written
[[check]]
name = "a"
run = "true"
# BEGIN generated by tools/ci/t_toml.py: inputs
inputs = ["a"]
# END generated
"""


class MergeGeneratedTest(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.git("init", "-q", "-b", "main")
        for key, value in (("user.name", "Test"), ("user.email", "test@example.org"),
                           ("commit.gpgsign", "false"), ("core.hooksPath", "/dev/null")):
            self.git("config", key, value)
        (self.root / ".githooks").mkdir()
        shutil.copy2(DRIVER, self.root / ".githooks" / "merge-generated")
        for driver, mode in (("generated", "whole"), ("generated-blocks", "blocks")):
            self.git("config", f"merge.{driver}.driver", f".githooks/merge-generated {mode} %O %A %B %P %L")
        (self.root / ".gitattributes").write_text("/Cargo.lock merge=generated\n/t.toml merge=generated-blocks\n")
        self.write("Cargo.lock", LOCK)
        self.write("t.toml", T_TOML)
        self.commit("base")

    def git(self, *args, check=True):
        return subprocess.run(["git", "-C", str(self.root), *args], capture_output=True, text=True, check=check)

    def write(self, name, text):
        (self.root / name).write_text(text)

    def read(self, name):
        return (self.root / name).read_text()

    def commit(self, message):
        self.git("add", "-A")
        self.git("commit", "-qm", message)

    def branches(self, path, main_text, change_text):
        """main and `change` both edit `path` from the base; rebase change onto main."""
        self.git("checkout", "-qb", "change")
        self.write(path, change_text)
        self.commit("change")
        self.git("checkout", "-q", "main")
        self.write(path, main_text)
        self.commit("main")
        self.git("checkout", "-q", "change")
        return self.git("rebase", "main", check=False)

    def test_lock_conflict_takes_main_and_keeps_the_rest_of_the_change(self):
        main = LOCK.replace(' "serde",\n', ' "rand",\n "serde",\n')
        change = LOCK.replace(' "serde",\n', ' "regex",\n "serde",\n') + (
            '\n[[package]]\nname = "zz"\nversion = "1.0.0"\n'
        )
        rebased = self.branches("Cargo.lock", main, change)
        self.assertEqual(rebased.returncode, 0, rebased.stderr)
        merged = self.read("Cargo.lock")
        self.assertIn(' "rand",\n "serde",', merged)
        self.assertNotIn('"regex"', merged)
        # The change's own hunk elsewhere in the file survives.
        self.assertIn('name = "zz"', merged)
        self.assertNotIn("<<<<<<<", merged)

    def test_lock_that_would_list_a_package_twice_is_main_whole(self):
        entry = '\n[[package]]\nname = "zz"\nversion = "1.0.0"\n'
        main = LOCK + entry
        # The same entry at another place merges cleanly line by line, but twice.
        change = LOCK.replace("version = 4\n", "version = 4\n" + entry)
        rebased = self.branches("Cargo.lock", main, change)
        self.assertEqual(rebased.returncode, 0, rebased.stderr)
        self.assertEqual(self.read("Cargo.lock"), main)

    def test_t_toml_conflict_in_a_generated_block_takes_main(self):
        rebased = self.branches("t.toml", T_TOML.replace('["a"]', '["a", "main"]'),
                                T_TOML.replace('["a"]', '["a", "change"]'))
        self.assertEqual(rebased.returncode, 0, rebased.stderr)
        self.assertIn('inputs = ["a", "main"]', self.read("t.toml"))

    def test_t_toml_conflict_outside_generated_blocks_stays_a_conflict(self):
        rebased = self.branches("t.toml", T_TOML.replace('run = "true"', 'run = "main"'),
                                T_TOML.replace('run = "true"', 'run = "change"'))
        self.assertNotEqual(rebased.returncode, 0)
        merged = self.read("t.toml")
        self.assertIn("<<<<<<<", merged)
        self.assertIn('run = "change"', merged)
        self.git("rebase", "--abort")


if __name__ == "__main__":
    unittest.main()
